using System.Collections.Generic;

namespace Rustegon.Driver;

/// <summary>Result of <c>InsertOneAsync</c>.</summary>
/// <param name="InsertedId">The document's <c>_id</c> (generated by the server when the document had none).</param>
public sealed record InsertOneResult(RDocValue InsertedId);

/// <summary>Result of <c>InsertManyAsync</c>.</summary>
/// <param name="InsertedIds">The ids, in input order.</param>
public sealed record InsertManyResult(IReadOnlyList<RDocValue> InsertedIds);

/// <summary>Result of the update and replace operations.</summary>
/// <param name="MatchedCount">Documents matched. A statement (non-id filter) reports the documents it wrote.</param>
/// <param name="ModifiedCount">Documents modified.</param>
/// <param name="UpsertedId">The id inserted by an upsert, else null.</param>
public sealed record UpdateResult(long MatchedCount, long ModifiedCount, RDocValue? UpsertedId = null);

/// <summary>Result of the delete operations.</summary>
/// <param name="DeletedCount">Documents deleted.</param>
public sealed record DeleteResult(long DeletedCount);

/// <summary>A failed operation of a bulk write (outside a transaction it does not fail the call).</summary>
/// <param name="Index">Position of the operation in the request.</param>
/// <param name="Error">The error.</param>
/// <param name="Message">The server's message.</param>
public sealed record BulkWriteError(int Index, RustegonError Error, string Message);

/// <summary>Result of <c>BulkWriteAsync</c>.</summary>
/// <param name="InsertedCount">Documents inserted (inserts and inserting upserts).</param>
/// <param name="MatchedCount">Documents matched by replaces, updates and replacing upserts.</param>
/// <param name="ModifiedCount">Documents modified.</param>
/// <param name="DeletedCount">Documents deleted.</param>
/// <param name="Errors">Failed operations, by index.</param>
public sealed record BulkWriteResult(long InsertedCount, long MatchedCount, long ModifiedCount, long DeletedCount, IReadOnlyList<BulkWriteError> Errors);

/// <summary>Build state of an index.</summary>
public enum IndexState
{
    /// <summary>Being built.</summary>
    Building,

    /// <summary>Ready and used by queries.</summary>
    Ready,

    /// <summary>The build failed.</summary>
    Failed,

    /// <summary>Maintained but not used by queries.</summary>
    Hidden,
}

/// <summary>An index of a collection.</summary>
/// <param name="Name">Index name.</param>
/// <param name="Keys">Keys, in order.</param>
/// <param name="Unique">Unique index.</param>
/// <param name="State">Build state.</param>
/// <param name="Error">Build error of a failed index.</param>
public sealed record IndexDescription(string Name, IReadOnlyList<IndexKey> Keys, bool Unique, IndexState State, string? Error = null);

/// <summary>Outcome of a commit, as the transaction status reports it (transactions.md §5).</summary>
public enum TransactionOutcome
{
    /// <summary>The transaction committed.</summary>
    Committed,

    /// <summary>The transaction did not commit and never will.</summary>
    Aborted,

    /// <summary>Still unknown (the commit is in progress or the state cannot be read).</summary>
    Unknown,
}
